import{U as e,gt as t,nt as n,rt as r}from"./chunks/framework.B3obAz7o.js";var i=JSON.parse(`{"title":"Cache Semantics","description":"","frontmatter":{},"headers":[],"relativePath":"cache.md","filePath":"cache.md","lastUpdated":1786757719000}`),a={name:`cache.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="cache-semantics" tabindex="-1">Cache Semantics <a class="header-anchor" href="#cache-semantics" aria-label="Permalink to “Cache Semantics”">​</a></h1><p>The Rust CLI and Node.js pipeline use the same default cache directory, <code>node_modules/.cache/fontmin-rs</code>, but maintain their own cache entries and runtime identities. Caching is opt-in. See <a href="./guide/config">Configuration</a> for the public options.</p><h2 id="consistency" tabindex="-1">Consistency <a class="header-anchor" href="#consistency" aria-label="Permalink to “Consistency”">​</a></h2><p>Each versioned cache root permits one writer at a time. Writers create an exclusive owner-tagged lock, write files through temporary paths, and atomically replace completed files. Concurrent processes therefore serialize cache updates rather than modifying the index or one entry simultaneously.</p><p>Lock release is owner-aware: a writer only removes the lock whose owner token it acquired. This prevents a delayed cleanup from removing a successor&#39;s lock. Readers treat an incomplete or missing entry as a cache miss and rebuild it.</p><h2 id="process-termination-and-cancellation" tabindex="-1">Process termination and cancellation <a class="header-anchor" href="#process-termination-and-cancellation" aria-label="Permalink to “Process termination and cancellation”">​</a></h2><p>Normal completion and errors release the lock. Cancelling an in-process Rust cache write also releases its lock when the write task is dropped.</p><p>When a process terminates while writing, the next writer detects that the recorded process is no longer running and reclaims the lock. A five-minute age limit remains as a fallback for legacy or unreadable owner identifiers. While recovering, the writer removes temporary <code>*.tmp</code> files from the versioned cache tree before starting a new update. Rust task cancellation performs the same cleanup while releasing its lock.</p><p>The acquisition retry window is approximately five seconds. A timeout means another live writer still owns the cache, or the cache is on a filesystem where local process ownership cannot be verified.</p><h2 id="operational-boundary" tabindex="-1">Operational boundary <a class="header-anchor" href="#operational-boundary" aria-label="Permalink to “Operational boundary”">​</a></h2><p>The lock protocol is designed for independent processes on one host. Do not share one writable cache directory between different machines over a network filesystem, because process identifiers are host-local. Give each machine its own cache directory and share only immutable build artifacts.</p>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};